        if (!is_last_used_block(b)) {
          return false;
        }
        auto alignedBytes = internal::round_to_alignment(Alignment, delta);
        if (_p + alignedBytes > _data + MaxSize) {
          return false;
        }
        _p += alignedBytes;
        b.length += alignedBytes;
        return true;
